<script>
(function () {
  "use strict";

  var STEP_MAX = 7;
  var LISTS = 24;
  var TYPES = ["d", "i", "s", "c"];

  var wizard = document.getElementById("wizard");
  var resultEl = document.getElementById("result");
  var tabs = Array.prototype.slice.call(document.querySelectorAll("[data-step-btn]"));
  var panes = Array.prototype.slice.call(document.querySelectorAll("[data-step-pane]"));
  var btnPrev = document.getElementById("btnPrev");
  var btnNext = document.getElementById("btnNext");
  var btnFinish = document.getElementById("btnFinish");
  var btnRestart = document.getElementById("btnRestart");
  var progressBar = document.getElementById("progressBar");
  var progressTrack = document.getElementById("progressTrack");
  var stepLabel = document.getElementById("stepLabel");
  var stepPercent = document.getElementById("stepPercent");
  var scoreLine = document.getElementById("scoreLine");
  var gauges = document.getElementById("gauges");
  var srStatus = document.getElementById("srStatus");
  var lists = Array.prototype.slice.call(document.querySelectorAll(".list"));
  var coarse = window.matchMedia ? window.matchMedia("(pointer: coarse)") : { matches: false };

  var HANDLE_SVG =
    '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false">' +
    '<circle cx="6" cy="3.5" r="1.35"/><circle cx="10" cy="3.5" r="1.35"/>' +
    '<circle cx="6" cy="8" r="1.35"/><circle cx="10" cy="8" r="1.35"/>' +
    '<circle cx="6" cy="12.5" r="1.35"/><circle cx="10" cy="12.5" r="1.35"/>' +
    "</svg>";

  var step = 0;
  var dnd = null;
  var initialOrders = [];

  function announce(text) {
    if (srStatus) srStatus.textContent = text;
  }

  /* ---------- items: number badge + drag handle ---------- */
  function updateNumbers(ul) {
    var items = ul.children;
    for (var i = 0; i < items.length; i++) {
      var num = items[i].querySelector(".item__num");
      if (num) num.textContent = String(i + 1);
      items[i].setAttribute("aria-posinset", String(i + 1));
      items[i].setAttribute("aria-setsize", String(items.length));
    }
  }

  function buildItemChrome(li) {
    if (!li.querySelector(".item__num")) {
      var num = document.createElement("span");
      num.className = "item__num";
      num.setAttribute("aria-hidden", "true");
      li.insertBefore(num, li.firstChild);
    }

    if (!li.querySelector(".handle")) {
      var handle = document.createElement("button");
      handle.type = "button";
      handle.className = "handle";
      handle.setAttribute("aria-label", "Изменить порядок: стрелки вверх и вниз");
      handle.innerHTML = HANDLE_SVG;
      li.appendChild(handle);
    }
  }

  function initLists() {
    lists.forEach(function (ul) {
      Array.prototype.forEach.call(ul.children, buildItemChrome);
      updateNumbers(ul);
      initialOrders.push(Array.prototype.slice.call(ul.children));

      ul.addEventListener("pointerdown", onPointerDown);
      ul.addEventListener("keydown", onHandleKeyDown);
      ul.addEventListener("dragstart", function (e) { e.preventDefault(); });
    });
  }

  /* ---------- pointer drag & drop ---------- */
  function onPointerDown(e) {
    if (dnd) return;
    if (typeof e.button === "number" && e.button !== 0) return;

    var ul = e.currentTarget;
    var li = e.target.closest ? e.target.closest(".item") : null;
    if (!li || li.parentElement !== ul) return;

    var fromHandle = !!(e.target.closest && e.target.closest(".handle"));
    if (!fromHandle && coarse.matches) return; // на тач-устройствах тянем только за ручку

    dnd = {
      ul: ul,
      li: li,
      pointerId: e.pointerId,
      startX: e.clientX,
      startY: e.clientY,
      active: false
    };

    window.addEventListener("pointermove", onPointerMove, { passive: false });
    window.addEventListener("pointerup", onPointerUp);
    window.addEventListener("pointercancel", onPointerUp);

    if (!fromHandle) e.preventDefault();
  }

  function onPointerMove(e) {
    if (!dnd || e.pointerId !== dnd.pointerId) return;

    if (!dnd.active) {
      var dx = e.clientX - dnd.startX;
      var dy = e.clientY - dnd.startY;
      if (Math.sqrt(dx * dx + dy * dy) < 5) return;
      dnd.active = true;
      dnd.li.classList.add("is-dragging");
      dnd.ul.classList.add("is-reordering");
      dnd.ul.__drag = dnd.li;
    }

    if (e.cancelable) e.preventDefault();

    var kids = Array.prototype.slice.call(dnd.ul.children);
    var before = null;

    for (var i = 0; i < kids.length; i++) {
      var el = kids[i];
      if (el === dnd.li) continue;
      var rect = el.getBoundingClientRect();
      if (e.clientY < rect.top + rect.height / 2) {
        before = el;
        break;
      }
    }

    if (before) {
      if (dnd.li !== before && dnd.li.nextElementSibling !== before) {
        dnd.ul.insertBefore(dnd.li, before);
        updateNumbers(dnd.ul);
      }
    } else if (dnd.ul.lastElementChild !== dnd.li) {
      dnd.ul.appendChild(dnd.li);
      updateNumbers(dnd.ul);
    }
  }

  function onPointerUp() {
    if (!dnd) return;
    var ul = dnd.ul;
    var li = dnd.li;

    window.removeEventListener("pointermove", onPointerMove);
    window.removeEventListener("pointerup", onPointerUp);
    window.removeEventListener("pointercancel", onPointerUp);

    li.classList.remove("is-dragging");
    ul.classList.remove("is-reordering");
    ul.__drag = null;

    var wasActive = dnd.active;
    dnd = null;
    updateNumbers(ul);

    if (wasActive) {
      announce("Позиция " + (indexOf(li) + 1) + " из " + ul.children.length);
    }
  }

  function indexOf(li) {
    var i = 0;
    var el = li;
    while ((el = el.previousElementSibling)) i++;
    return i;
  }

  /* ---------- keyboard reordering ---------- */
  function onHandleKeyDown(e) {
    var handle = e.target.closest ? e.target.closest(".handle") : null;
    if (!handle) return;

    var li = handle.parentElement;
    var ul = li.parentElement;
    var moved = false;

    if (e.key === "ArrowUp" && li.previousElementSibling) {
      ul.insertBefore(li, li.previousElementSibling);
      moved = true;
    } else if (e.key === "ArrowDown" && li.nextElementSibling) {
      ul.insertBefore(li.nextElementSibling, li);
      moved = true;
    } else if (e.key === "Home" && li.previousElementSibling) {
      ul.insertBefore(li, ul.firstElementChild);
      moved = true;
    } else if (e.key === "End" && li.nextElementSibling) {
      ul.appendChild(li);
      moved = true;
    }

    if (!moved) return;
    e.preventDefault();
    updateNumbers(ul);
    handle.focus({ preventScroll: true });
    announce("Позиция " + (indexOf(li) + 1) + " из " + ul.children.length);
  }

  /* ---------- steps ---------- */
  function render() {
    for (var i = 0; i < tabs.length; i++) {
      var isActive = Number(tabs[i].getAttribute("data-step-btn")) === step;
      tabs[i].classList.toggle("is-active", isActive);
      tabs[i].setAttribute("aria-selected", isActive ? "true" : "false");
      tabs[i].setAttribute("tabindex", isActive ? "0" : "-1");
    }

    for (var j = 0; j < panes.length; j++) {
      panes[j].classList.toggle("is-active", Number(panes[j].getAttribute("data-step-pane")) === step);
    }

    btnPrev.disabled = step === 0;
    btnNext.hidden = step === STEP_MAX;
    btnFinish.hidden = step !== STEP_MAX;

    var pct = ((step + 1) / 8) * 100;
    progressBar.style.width = pct + "%";
    progressTrack.setAttribute("aria-valuenow", String(step + 1));
    stepLabel.textContent = "Шаг " + (step + 1) + " из 8";
    stepPercent.textContent = Math.round(pct) + "%";

    var activeTab = tabs[step];
    if (activeTab && coarse.matches && activeTab.scrollIntoView) {
      activeTab.scrollIntoView({ behavior: "smooth", block: "nearest", inline: "center" });
    }
  }

  function setStep(next) {
    var target = Math.max(0, Math.min(STEP_MAX, next));
    var changed = target !== step;
    step = target;
    render();

    if (changed && wizard.getBoundingClientRect().top < 0) {
      wizard.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  }

  /* ---------- scoring (как в оригинале: позиция 0 — «наиболее», позиция 3 — «наименее») ---------- */
  function collectPayload() {
    var payload = [];
    for (var l = 0; l < lists.length; l++) {
      var items = lists[l].children;
      for (var pos = 0; pos < items.length; pos++) {
        payload.push({
          list: l,
          pos: pos,
          type: items[pos].getAttribute("data-type")
        });
      }
    }
    return payload;
  }

  function score(payload) {
    var maj = [];
    var min = [];

    for (var i = 0; i < payload.length; i++) {
      if (payload[i].pos === 0) maj.push(payload[i].type);
      if (payload[i].pos === 3) min.push(payload[i].type);
    }

    function count(arr, ch) {
      var n = 0;
      for (var k = 0; k < arr.length; k++) if (arr[k] === ch) n++;
      return n;
    }

    return {
      d: count(maj, "d") - count(min, "d"),
      i: count(maj, "i") - count(min, "i"),
      s: count(maj, "s") - count(min, "s"),
      c: count(maj, "c") - count(min, "c")
    };
  }

  function renderResult(res) {
    var parts = [];
    for (var i = 0; i < TYPES.length; i++) {
      parts.push(TYPES[i].toUpperCase() + ":" + res[TYPES[i]]);
    }
    scoreLine.textContent = parts.join(", ");

    for (var j = 0; j < TYPES.length; j++) {
      var key = TYPES[j];
      var row = gauges.querySelector('[data-gauge="' + key + '"]');
      if (!row) continue;
      var value = res[key];
      var fill = row.querySelector(".gauge__fill");
      var valEl = row.querySelector(".gauge__value");
      var half = (Math.abs(value) / LISTS) * 50;
      fill.style.width = half + "%";
      fill.style.left = value >= 0 ? "50%" : 50 - half + "%";
      fill.classList.toggle("gauge__fill--neg", value < 0);
      valEl.textContent = String(value);
    }
  }

  function finishTest() {
    renderResult(score(collectPayload()));
    wizard.hidden = true;
    resultEl.hidden = false;
    window.scrollTo({ top: 0, behavior: "smooth" });
    btnRestart.focus({ preventScroll: true });
  }

  function restartTest() {
    for (var l = 0; l < lists.length; l++) {
      var ul = lists[l];
      while (ul.firstChild) ul.removeChild(ul.firstChild);
      var order = initialOrders[l];
      for (var i = 0; i < order.length; i++) ul.appendChild(order[i]);
      updateNumbers(ul);
    }
    step = 0;
    render();
    resultEl.hidden = true;
    wizard.hidden = false;
    window.scrollTo({ top: 0, behavior: "smooth" });
    tabs[0].focus({ preventScroll: true });
  }

  /* ---------- wiring ---------- */
  tabs.forEach(function (tab) {
    tab.addEventListener("click", function () {
      setStep(Number(tab.getAttribute("data-step-btn")));
    });
  });

  document.getElementById("tabs").addEventListener("keydown", function (e) {
    if (e.key !== "ArrowRight" && e.key !== "ArrowLeft") return;
    var dir = e.key === "ArrowRight" ? 1 : -1;
    var next = (step + dir + tabs.length) % tabs.length;
    setStep(next);
    tabs[next].focus({ preventScroll: true });
    e.preventDefault();
  });

  btnPrev.addEventListener("click", function () { setStep(step - 1); });
  btnNext.addEventListener("click", function () { setStep(step + 1); });
  btnFinish.addEventListener("click", finishTest);
  btnRestart.addEventListener("click", restartTest);

  initLists();
  render();
})();
</script>
</body>
</html>
